package com.stocksense.ledger; import com.stocksense.product.Product; import com.stocksense.warehouse.Location; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.Instant; @Entity @Getter @Setter @NoArgsConstructor public class StockMovement { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String movementNumber; @ManyToOne(optional=false) private Product product; @Enumerated(EnumType.STRING) @Column(nullable=false) private MovementType type; @ManyToOne private Location sourceLocation; @ManyToOne private Location destinationLocation; @Column(nullable=false,precision=19,scale=3) private BigDecimal quantity; private String referenceType; private String referenceId; private String performedBy; @Column(nullable=false) private Instant createdAt=Instant.now(); }
